# -*- coding: utf-8 -*-
'''blender_run —— 在无头 Blender 中执行用户 bpy 代码。'''
import glob
import json
import os
import shutil
import subprocess
import sys
import tempfile

TIMEOUT = 105  # Parable 工具层 120s 硬超时，这里留余量自行终止，错误信息更友好


def find_blender(explicit=None):
    cands = []
    if explicit:
        cands.append(explicit)
    p = shutil.which("blender")
    if p:
        cands.append(p)
    cands += glob.glob(r"C:\Program Files\Blender Foundation\Blender *\blender.exe")
    for drive in "CDEFGH":
        cands += glob.glob(rf"{drive}:\SteamLibrary\steamapps\common\Blender\blender.exe")
        cands += glob.glob(rf"{drive}:\Steam\steamapps\common\Blender\blender.exe")
        cands += glob.glob(rf"{drive}:\Program Files (x86)\Steam\steamapps\common\Blender\blender.exe")
    for c in cands:
        if c and os.path.isfile(c):
            return os.path.normpath(c)
    return None


def main():
    try:
        args = json.loads(os.environ.get("PARABLE_TOOL_ARGS") or "{}")
    except ValueError:
        args = {}
    code = args.get("code") or ""
    if not code.strip():
        print("缺少 code 参数（要执行的 bpy Python 代码）。")
        sys.exit(2)
    exe = find_blender(args.get("blender_path"))
    if not exe:
        print("未找到 Blender：先运行 blender_info 看探测路径，"
              "或用 blender_path 参数手动指定 blender.exe。")
        sys.exit(2)
    ws = os.environ.get("PARABLE_TOOL_WORKSPACE") or os.getcwd()
    if ws and os.path.isdir(ws):
        os.chdir(ws)
    tmp = os.path.join(tempfile.gettempdir(), f"parable-blender-{os.getpid()}.py")
    with open(tmp, "w", encoding="utf-8") as f:
        f.write(code)
    cmd = [exe, "-b"]
    bf = args.get("file")
    if bf:
        cmd += [bf]
    cmd += ["-P", tmp]
    try:
        r = subprocess.run(cmd, capture_output=True, text=True, timeout=TIMEOUT,
                           errors="replace")
    except subprocess.TimeoutExpired as e:
        head = (e.stdout or b"")
        if isinstance(head, bytes):
            head = head.decode("utf-8", "replace")
        tail = (e.stderr or b"")
        if isinstance(tail, bytes):
            tail = tail.decode("utf-8", "replace")
        print(f"已终止：脚本超过 {TIMEOUT}s 未结束（Parable 工具层 120s 硬上限）。")
        print("长任务请拆块执行，或把 blender 命令交给 bash 工具挂后台终端跑。")
        if head.strip():
            print("[stdout 已产出部分]\n" + head[-4000:])
        if tail.strip():
            print("[stderr 已产出部分]\n" + tail[-2000:])
        sys.exit(3)
    except FileNotFoundError:
        print(f"无法启动 {exe}")
        sys.exit(2)
    finally:
        try:
            os.remove(tmp)
        except OSError:
            pass
    out = (r.stdout or "").strip()
    err = (r.stderr or "").strip()
    if out:
        print(out[-12000:])
    if err:
        # Blender 把脚本异常也写进 stderr；原样带回给模型判断
        print("[stderr]\n" + err[-6000:])
    if r.returncode != 0:
        print(f"[blender 退出码 {r.returncode}]")
        sys.exit(r.returncode)


main()

# -*- coding: utf-8 -*-
'''blender_render —— 无头渲染 .blend 的帧区间。'''
import glob
import json
import os
import shutil
import subprocess
import sys

TIMEOUT = 105


def find_blender(explicit=None):
    cands = []
    if explicit:
        cands.append(explicit)
    p = shutil.which("blender")
    if p:
        cands.append(p)
    cands += glob.glob(r"C:\Program Files\Blender Foundation\Blender *\blender.exe")
    for drive in "CDEFGH":
        cands += glob.glob(rf"{drive}:\SteamLibrary\steamapps\common\Blender\blender.exe")
        cands += glob.glob(rf"{drive}:\Steam\steamapps\common\Blender\blender.exe")
        cands += glob.glob(rf"{drive}:\Program Files (x86)\Steam\steamapps\common\Blender\blender.exe")
    for c in cands:
        if c and os.path.isfile(c):
            return os.path.normpath(c)
    return None


def main():
    try:
        args = json.loads(os.environ.get("PARABLE_TOOL_ARGS") or "{}")
    except ValueError:
        args = {}
    bf = args.get("file") or ""
    out = args.get("output") or ""
    if not bf or not out:
        print("需要 file（.blend 工程路径）与 output（输出前缀）两个参数。")
        sys.exit(2)
    exe = find_blender(args.get("blender_path"))
    if not exe:
        print("未找到 Blender：先运行 blender_info，或用 blender_path 参数指定。")
        sys.exit(2)
    ws = os.environ.get("PARABLE_TOOL_WORKSPACE") or os.getcwd()
    if ws and os.path.isdir(ws):
        os.chdir(ws)
    cmd = [exe, "-b", bf, "-o", out]
    if args.get("start") is not None:
        cmd += ["-s", str(int(args["start"]))]
    if args.get("end") is not None:
        cmd += ["-e", str(int(args["end"]))]
    cmd += ["-a"]
    print("运行：" + subprocess.list2cmdline(cmd))
    try:
        r = subprocess.run(cmd, capture_output=True, text=True, timeout=TIMEOUT,
                           errors="replace")
    except subprocess.TimeoutExpired:
        print(f"已终止：渲染超过 {TIMEOUT}s 未结束。")
        print("建议：缩小分辨率/帧区间分块渲染，或改用 bash 工具把同一命令挂后台终端（不受 120s 限制）。")
        sys.exit(3)
    out_txt = (r.stdout or "").strip()
    err_txt = (r.stderr or "").strip()
    # 渲染报告行 stdout/stderr 都可能出现，两边都扫「Saved:」
    saved = [ln for ln in (out_txt + "\n" + err_txt).splitlines()
             if "Saved:" in ln or "FileOutputError" in ln]
    if saved:
        print("\n".join(saved[-20:]))
    if out_txt:
        print(out_txt[-3000:])
    if r.returncode != 0:
        print("[stderr 末尾]\n" + err_txt[-3000:] if err_txt else "")
        print(f"[blender 退出码 {r.returncode}]")
        sys.exit(r.returncode)
    if not saved:
        print("（未检测到 Saved: 行——检查 output 路径与工程输出设置是否有效）")


main()
